readonly results = toSignal(
  this.searchControl.valueChanges.pipe(
    debounceTime(300),
    distinctUntilChanged(),
    switchMap(query => this.customers.search(query).pipe(
      catchError(() => of<Customer[]>([]))
    )),
    takeUntilDestroyed(),
  ),
  { initialValue: [] as Customer[] },
);

