export {};

interface Deferred {
  promise: Promise<string[]>;
  resolve: (value: string[]) => void;
}

function deferred(): Deferred {
  let resolve!: (value: string[]) => void;
  const promise = new Promise<string[]>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

class SearchBox {
  private latest = 0;
  state: 'idle' | 'loading' | 'done' = 'idle';

  async search(query: string, fetcher: (query: string) => Promise<string[]>): Promise<void> {
    // TODO 1 : numérote la requête (incrémente this.latest) et passe l'état à 'loading'
    // TODO 2 : attends le résultat du fetcher
    // TODO 3 : si une requête plus récente a été lancée entre-temps, affiche "ignoré: <query>" et arrête-toi
    // TODO 4 : sinon passe l'état à 'done' et affiche "affiché: <query> -> <résultats séparés par ", ">"
  }
}

async function main(): Promise<void> {
  const box = new SearchBox();
  const slow = deferred();
  const fast = deferred();
  const first = box.search('a', () => slow.promise);
  const second = box.search('ab', () => fast.promise);
  console.log(`État: ${box.state}`);
  fast.resolve(['ab-1', 'ab-2']);
  await second;
  slow.resolve(['a-1']);
  await first;
  console.log(`État final: ${box.state}`);
}

main();
